<template><Teleport to="body"><div v-if="open" class="monitor-modal-backdrop" @click.self="$emit('close')"><section class="monitor-modal device-dialog" role="dialog" aria-modal="true" aria-label="监控设备" @keydown.esc="$emit('close')">
<header><div><h2>{{editing?(editId?'编辑相机':'添加相机'):'设备'}}</h2><small>{{editing?'在视频墙显示后自动连接真实视频源':'选择需要显示的视频通道'}}</small></div><button class="icon-button" aria-label="关闭设备窗口" @click="$emit('close')"><X :size="20"/></button></header>
<div class="monitor-modal-body"><p v-if="error" class="error-banner" role="alert">{{error}}</p>
<form v-if="editing" @submit.prevent="save"><fieldset :disabled="busy"><label class="form-field">相机名称<input v-model="form.label" required maxlength="80" autocomplete="off"/></label><div class="field-pair"><label class="form-field">主机地址<input v-model="form.host" required placeholder="192.168.1.100" autocomplete="off"/></label><label class="form-field small-field">RTSP 端口<input v-model.number="form.port" type="number" min="1" max="65535" required/></label></div><div class="field-pair"><label class="form-field">设备账号<input v-model="form.username" autocomplete="off"/></label><label class="form-field">设备密码<input v-model="form.password" type="password" autocomplete="new-password" :placeholder="editId?'留空保留已有密码':'设备密码'"/></label></div><div class="field-pair"><label class="form-field">视频通道<input v-model.number="form.channel" type="number" min="1" max="64" required/></label><label class="form-field">码流<select v-model="form.stream"><option value="main">主码流</option><option value="sub">子码流</option></select></label></div><label v-if="!stereoEditing" class="form-field">RTSP 路径 <small>可留空使用标准通道地址</small><input v-model="form.path" placeholder="/Streaming/Channels/101" maxlength="1024"/></label><p class="muted dialog-note">{{stereoEditing?'此通道参与双目检测与定位，配置变更将重连双目服务。':'此通道用于实时视频监看。双目定位由 C1 / C2 提供。'}}</p><div class="dialog-actions"><button type="button" class="btn" @click="editing=false">返回设备</button><button class="btn primary" :disabled="busy">{{busy?'正在保存…':'保存配置'}}</button></div></fieldset></form>
<template v-else><div class="device-search"><Search :size="17"/><input v-model="search" aria-label="搜索设备" placeholder="搜索相机名称或地址"/><button v-if="auth.can('devices')" class="btn primary" @click="edit()"><Plus :size="16"/>添加</button></div><div class="monitor-device-list"><article v-for="device in filtered" :key="device.id"><label class="visibility-choice"><input type="checkbox" :checked="!hiddenIds.includes(device.id)" :aria-label="'显示 '+device.code" @change="$emit('visibility',device.id,($event.target as HTMLInputElement).checked)"/><Video :size="21"/><div><strong>{{device.code}} <span>{{device.label}}</span></strong><small>{{device.host||'尚未配置地址'}} <span class="device-live" :class="{online:device.runtime?.state==='streaming'&&device.runtime?.frameAvailable}">· {{device.runtime?.state==='streaming'?(device.runtime?.frameAvailable?'在线':'等待画面'):device.host?'未连接':'未配置'}}</span></small></div></label><div class="device-row-actions"><button class="icon-button" title="在视频墙显示" :aria-label="'定位 '+device.code" @click="$emit('focus',device.id)"><Focus :size="16"/></button><template v-if="auth.can('devices')"><button class="icon-button" :disabled="testing===device.id||!device.host" :title="device.host?'测试RTSP端口连通性':'请先配置地址'" :aria-label="'测试 '+device.code+' 端口'" @click="test(device)"><component :is="testing===device.id?LoaderCircle:PlugZap" :size="16" :class="{spin:testing===device.id}"/></button><button class="icon-button" :aria-label="'编辑 '+device.code" title="编辑相机" @click="edit(device)"><Pencil :size="16"/></button><button v-if="!device.isStereo" class="icon-button remove-device" :disabled="busy" :aria-label="'删除 '+device.code" title="删除相机" @click="remove(device)"><Trash2 :size="16"/></button></template></div></article><p v-if="!filtered.length" class="dialog-note muted">{{monitor.loaded?'没有匹配的相机':'正在读取设备…'}}</p></div><div v-if="testResult" class="port-result" role="status">{{testResult}}</div>
<section class="monitor-service"><header><h3>目标检测</h3><span>{{camera.status.detecting?(camera.status.engineState==='ready'?'运行中':'正在准备'):'已停止'}}</span></header><p>{{camera.status.detecting?camera.status.engineState==='ready'?'双目检测与定位正在接收实时画面。':camera.status.error||'等待推理服务就绪':'启动后，在视频画面与已配准模型中显示真实检测目标。'}}</p><div class="dialog-actions"><button v-if="auth.can('review')" class="btn" :disabled="camera.detectionBusy||(!camera.status.detecting&&!framesAvailable)" :title="!framesAvailable&&!camera.status.detecting?'等待 C1 或 C2 提供实际画面':'切换目标检测服务'" @click="camera.toggleDetection()"><component :is="camera.status.detecting?Pause:Play" :size="16"/>{{camera.detectionBusy?'处理中…':camera.status.detecting?'停止监测':'开始监测'}}</button><button v-if="auth.can('devices')" class="btn" @click="$emit('open-scene')"><MapPin :size="16"/>模型坐标配准</button></div></section>
</template></div></section></div></Teleport></template>
<script setup lang="ts">
import {computed,ref,watch} from 'vue';
import {X,Search,Plus,Video,Focus,Pencil,Trash2,PlugZap,LoaderCircle,Pause,Play,MapPin} from 'lucide-vue-next';
import {http} from '@/api/http';
import {useMonitorStore} from '@/stores/monitor';
import {useCameraStore} from '@/stores/camera';
import {useAuthStore} from '@/stores/auth';
import type {MonitorDevice} from '@/types/monitor';
import {useDialogFocus} from '@/lib/dialog-focus';
const props=defineProps<{open:boolean;hiddenIds:string[];initialDeviceId?:string|null}>();
const emit=defineEmits<{close:[];visibility:[id:string,visible:boolean];focus:[id:string];updated:[id:string];'open-scene':[]}>();
useDialogFocus(()=>props.open,'.device-dialog',()=>emit('close'));
const monitor=useMonitorStore(),camera=useCameraStore(),auth=useAuthStore();
const search=ref(''),editing=ref(false),editId=ref(''),busy=ref(false),testing=ref(''),testResult=ref(''),error=ref('');
const defaults=()=>({label:'',host:'',port:554,username:'admin',password:'',channel:1,stream:'main',path:''});const form=ref(defaults());
const filtered=computed(()=>monitor.devices.filter(d=>(d.code+' '+d.label+' '+d.host).toLowerCase().includes(search.value.trim().toLowerCase())));
const stereoEditing=computed(()=>editId.value==='camera1'||editId.value==='camera2');
const framesAvailable=computed(()=>Object.values(camera.status.cameras).some(c=>c.frameAvailable&&c.state==='streaming'));
watch(()=>props.open,value=>{if(!value)return;error.value='';testResult.value='';editing.value=false;const device=monitor.devices.find(d=>d.id===props.initialDeviceId);if(device&&auth.can('devices'))edit(device)});
function edit(device?:MonitorDevice){editId.value=device?.id||'';form.value=device?{label:device.label,host:device.host,port:device.port,username:device.username,channel:device.channel,stream:device.stream,path:device.path||'',password:''}:defaults();editing.value=true;error.value=''}
async function save(){if(busy.value)return;busy.value=true;error.value='';try{const payload={...form.value};if(editId.value&&!payload.password)delete(payload as Partial<typeof payload>).password;const result=editId.value?await http.patch('/monitor/devices/'+encodeURIComponent(editId.value),payload):await http.post('/monitor/devices',payload);await monitor.refresh();emit('updated',result.data.device?.id||editId.value);editing.value=false;camera.toast(result.data.applied===false?result.data.message||'配置已保存，等待服务恢复':'相机配置已保存',result.data.applied===false?'info':'success')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function test(device:MonitorDevice){testing.value=device.id;testResult.value='';error.value='';try{const{data}=await http.post('/monitor/devices/'+encodeURIComponent(device.id)+'/test');testResult.value=device.code+' · '+(data.connected?'RTSP 端口可达，延迟 '+data.latencyMs+' ms（不代表视频认证通过）':'端口不可达，请检查设备地址、端口与网络')}catch(e){error.value=(e as Error).message}finally{testing.value=''}}
async function remove(device:MonitorDevice){if(!window.confirm('删除 '+device.label+' 的接入配置？'))return;busy.value=true;try{await http.delete('/monitor/devices/'+encodeURIComponent(device.id));await monitor.refresh();camera.toast('相机已移除','success')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script>
